		}
	}

	rfapi_un_options_free(ri->un_options); 
	ri->un_options = rfapi_encap_tlv_to_un_option(bpi->attr);




	if (bpi->extra && decode_rd_type(bpi->extra->vnc->vnc.import.rd.val) ==
