		(void)rfapiEcommunityGetLNI(bgp_attr_get_ecommunity(bpi->attr),
					    &vo->v.l2addr.logical_net_id);
		(void)rfapiEcommunityGetEthernetTag(
			bgp_attr_get_ecommunity(bpi->attr),
			&vo->v.l2addr.tag_id);


		vo->v.l2addr.local_nve_id =
			bpi->extra->vnc->vnc.import.rd.val[1];


		vo->v.l2addr.label =
			BGP_PATH_INFO_NUM_LABELS(bpi)
				? decode_label(&bpi->extra->labels->label[0])
				: MPLS_INVALID_LABEL;

		rfapi_vn_options_free(
			ri->vn_options); 
		ri->vn_options = vo;
	}




	if (bpi->extra && bpi->extra->vnc->vnc.import.aux_prefix.family) {
		ri->rk.aux_prefix = bpi->extra->vnc->vnc.import.aux_prefix;
	}
}

int bgp_flowspec_bitmask_decode(enum bgp_flowspec_util_nlri_t type,
				 uint8_t *nlri_ptr,
				 uint32_t max_len,
				 void *result, int *error)
{
	int op[8];
	int len, value_size, loop = 0, value;
	char *ptr = (char *)result; 
	struct bgp_pbr_match_val *mval = (struct bgp_pbr_match_val *)result;
	uint32_t offset = 0;
	int len_string = BGP_FLOWSPEC_STRING_DISPLAY_MAX;
	int len_written;

	*error = 0;


	if (max_len < 1) {
		*error = -1;
		return 0;
	}

	do {
		if (loop > BGP_PBR_MATCH_VAL_MAX) {
			*error = -2;
			return offset;
		}

		hex2bin(&nlri_ptr[offset], op);

		if (op[1] == 1 && loop == 0)
			*error = -1;
		offset++;
		len = 2 * op[2] + op[3];
		value_size = 1 << len;

		if (offset > max_len || (uint32_t)value_size > (max_len - offset)) {
			*error = -1;
			break;
		}

		value = hexstr2num(&nlri_ptr[offset], value_size);
		switch (type) {
		case BGP_FLOWSPEC_RETURN_STRING:
			if (op[1] == 1 && loop != 0) {
				len_written = snprintf(ptr, len_string,
						       ",&");
				len_string -= len_written;
				ptr += len_written;
			} else if (op[1] == 0 && loop != 0) {
				len_written = snprintf(ptr, len_string,
						      ",|");
				len_string -= len_written;
				ptr += len_written;
			}
			if (op[7] == 1) {
				len_written = snprintf(ptr, len_string,
					       "= ");
				len_string -= len_written;
				ptr += len_written;
			} else {
				len_written = snprintf(ptr, len_string,
						       "∋ ");
				len_string -= len_written;
				ptr += len_written;
			}
			if (op[6] == 1) {
				len_written = snprintf(ptr, len_string,
					       "! ");
				len_string -= len_written;
				ptr += len_written;
			}
			len_written = snprintf(ptr, len_string,
				       "%d", value);
			len_string -= len_written;
			ptr += len_written;
			break;
		case BGP_FLOWSPEC_CONVERT_TO_NON_OPAQUE:

			if (*error == -2)
				break;
			mval->value = value;
			if (op[6] == 1) {

				SET_FLAG(mval->compare_operator,
					 OPERATOR_COMPARE_LESS_THAN);
				SET_FLAG(mval->compare_operator,
					 OPERATOR_COMPARE_GREATER_THAN);
			} else
				SET_FLAG(mval->compare_operator,
					 OPERATOR_COMPARE_EQUAL_TO);
			if (op[7] == 1)
				SET_FLAG(mval->compare_operator,
					 OPERATOR_COMPARE_EXACT_MATCH);
			if (op[1] == 1)
				mval->unary_operator =
					OPERATOR_UNARY_AND;
			else
				mval->unary_operator =
					OPERATOR_UNARY_OR;
			mval++;
			break;
		case BGP_FLOWSPEC_VALIDATE_ONLY:
		case BGP_FLOWSPEC_RETURN_JSON:

			break;
		}
		offset += value_size;
		loop++;
	} while (op[0] == 0 && offset < max_len - 1);
	if (offset > max_len)
		*error = -1;

	if (*error == 0)
		*error = loop;
	return offset;
}

