}

void
format_fractional_part_nsecs(gchar *buf, size_t buflen, guint32 nsecs, const char *decimal_point, int precision)
{
	gsize decimal_point_len;
	gint8 num_buf[CHARS_NANOSECONDS];
	gint8 *num_end = &num_buf[CHARS_NANOSECONDS];
	gint8 *num_ptr;
	size_t num_len;

	ws_assert(precision != 0);

	if (buflen == 0) {




		return;
	}




	decimal_point_len = g_strlcpy(buf, decimal_point, buflen);
	if (decimal_point_len >= buflen) {




		return;
	}
	buf += decimal_point_len;
	buflen -= decimal_point_len;
















	switch (precision) {

	case 1:



		num_ptr = uint_to_str_back_len(num_end,
		    nsecs / 100000000, precision);
		break;

	case 2:



		num_ptr = uint_to_str_back_len(num_end,
		    nsecs / 10000000, precision);
		break;

	case 3:



		num_ptr = uint_to_str_back_len(num_end,
		    nsecs / 1000000, precision);
		break;

	case 4:



		num_ptr = uint_to_str_back_len(num_end,
		    nsecs / 100000, precision);
		break;

	case 5:



		num_ptr = uint_to_str_back_len(num_end,
		    nsecs / 10000, precision);
		break;

	case 6:



		num_ptr = uint_to_str_back_len(num_end,
		    nsecs / 1000, precision);
		break;

	case 7:



		num_ptr = uint_to_str_back_len(num_end,
		    nsecs / 100, precision);
		break;

	case 8:



		num_ptr = uint_to_str_back_len(num_end,
		    nsecs / 10, precision);
		break;

	case 9:



		num_ptr = uint_to_str_back_len(num_end, nsecs,
		    precision);
		break;

	default:
		ws_assert_not_reached();
		break;
	}









	num_len = MIN((size_t)(num_end - num_ptr), buflen - 1);
	if (num_len == 0) {



		return;
	}




	memcpy(buf, num_ptr, num_len);




	*(buf + num_len) = '\0';
}

int
format_fractional_part_nsecs(gchar *buf, size_t buflen, guint32 nsecs, const char *decimal_point, int precision)
{
	gchar *ptr;
	size_t remaining;
	int num_bytes;
	gsize decimal_point_len;
	guint32 frac_part;
	gint8 num_buf[CHARS_NANOSECONDS];
	gint8 *num_end = &num_buf[CHARS_NANOSECONDS];
	gint8 *num_ptr;
	size_t num_len;

	ws_assert(precision != 0);

	if (buflen == 0) {




		return 0;
	}





	if (nsecs >= 1000000000U) {
		num_bytes = snprintf(buf, buflen, "%s(%u nanoseconds)",
		    decimal_point, nsecs);
		if ((unsigned int)num_bytes >= buflen) {







			return (int)(buflen - 1);
		}
		return num_bytes;
	}

	ptr = buf;
	remaining = buflen;
	num_bytes = 0;




	decimal_point_len = g_strlcpy(buf, decimal_point, buflen);
	if (decimal_point_len >= buflen) {







		return (int)(buflen - 1);
	}
	ptr += decimal_point_len;
	remaining -= decimal_point_len;
	num_bytes += decimal_point_len;
















	switch (precision) {

	case 1:



		frac_part = nsecs / 100000000U;
		break;

	case 2:



		frac_part = nsecs / 10000000U;
		break;

	case 3:



		frac_part = nsecs / 1000000U;
		break;

	case 4:



		frac_part = nsecs / 100000U;
		break;

	case 5:



		frac_part = nsecs / 10000U;
		break;

	case 6:



		frac_part = nsecs / 1000U;
		break;

	case 7:



		frac_part = nsecs / 100U;
		break;

	case 8:



		frac_part = nsecs / 10U;
		break;

	case 9:



		frac_part = nsecs;
		break;

	default:
		ws_assert_not_reached();
		break;
	}

	num_ptr = uint_to_str_back_len(num_end, frac_part, precision);









	num_len = MIN((size_t)(num_end - num_ptr), remaining - 1);
	if (num_len == 0) {




		return num_bytes;
	}




	memcpy(ptr, num_ptr, num_len);
	ptr += num_len;
	num_bytes += num_len;




	*ptr = '\0';
	return num_bytes;
}

int razer_get_usb_response(struct usb_device *usb_dev, uint report_index, struct razer_report* request_report, uint response_index, struct razer_report* response_report, ulong wait_min, ulong wait_max)
{
    uint request = HID_REQ_GET_REPORT; 
    uint request_type = USB_TYPE_CLASS | USB_RECIP_INTERFACE | USB_DIR_IN; 
    uint value = 0x300;

    uint size = RAZER_USB_REPORT_LEN; 
    int len;
    int retval;
    int result = 0;
    char *buf;

    buf = kzalloc(sizeof(struct razer_report), GFP_KERNEL);
    if (buf == NULL)
        return -ENOMEM;



    retval = razer_send_control_msg(usb_dev, request_report, report_index, wait_min, wait_max);


    len = usb_control_msg(usb_dev, usb_rcvctrlpipe(usb_dev, 0),
                          request,         
                          request_type,    
                          value,           
                          response_index,  
                          buf,             
                          size,
                          USB_CTRL_SET_TIMEOUT);

    memcpy(response_report, buf, sizeof(struct razer_report));
    kfree(buf);


    if(len != 90) {
        printk(KERN_WARNING "razer driver: Invalid USB response. USB Report length: %d\n", len);
        result = 1;
    }

    return result;
}

