                          USB_CTRL_SET_TIMEOUT);

    memcpy(response_report, buf, sizeof(struct razer_report));
    kfree(buf);


    if(len != 90) {
        printk(KERN_WARNING "razer driver: Invalid USB response. USB Report length: %d\n", len);
        result = 1;
    }

    if (WARN_ONCE(response_report->data_size > ARRAY_SIZE(response_report->arguments),
                  "Field data_size %d in response is bigger than arguments\n",
                  response_report->data_size)) {

        response_report->data_size = ARRAY_SIZE(response_report->arguments);
        return -EINVAL;
    }

    return result;
}

static FILE* hsm_mk_change_op_open(const char *id, CK_SLOT_ID slot_id,
                                   const char *mode)
{
    char hsm_mk_change_file[PATH_MAX];
    FILE *fp;

    if (slot_id != (CK_SLOT_ID)-1) {
        if (ock_snprintf(hsm_mk_change_file, PATH_MAX, "%s/%s-%lu",
                         OCK_HSM_MK_CHANGE_PATH, id, slot_id) != 0) {
            TRACE_ERROR("HSM_MK_CHANGE directory path buffer overflow\n");
            return NULL;
        }
    } else {
        if (ock_snprintf(hsm_mk_change_file, PATH_MAX, "%s/%s",
                         OCK_HSM_MK_CHANGE_PATH, id) != 0) {
            TRACE_ERROR("HSM_MK_CHANGE directory path buffer overflow\n");
            return NULL;
        }
    }

    TRACE_DEVEL("file to open: %s mode: %s\n", hsm_mk_change_file, mode);

    fp = fopen(hsm_mk_change_file, mode);
    if (fp == NULL) {
        TRACE_ERROR("%s fopen(%s, %s): %s\n", __func__,
                        hsm_mk_change_file, mode, strerror(errno));
