static int set_file_permissions(const char *fname, const struct group *group,
                                bool recursive)
{
    struct stat sb;
    struct passwd *pwd;
    int err, i, rc, mode;
    bool found = false;
    uid_t uid = (uid_t)-1;
    DIR *dir;
    struct dirent *entry;
    char ent[PATH_MAX];

    pr_verbose("Setting permissions for '%s' with group '%s'", fname,
               group->gr_name);

    if (stat(fname, &sb) != 0) {
        warnx("'%s' does not exist.", fname);
        return -1;
    }

    if (sb.st_uid != 0) {

        pwd = getpwuid(sb.st_uid);


        for (i = 0; pwd != NULL && group->gr_mem[i] != NULL; i++) {
            if (strcmp(group->gr_mem[i], pwd->pw_name) == 0) {
                found = true;
                break;
            }
        }

        if (!found)
            uid = 0; 
    }


    if (S_ISDIR(sb.st_mode))
        mode = S_IRUSR | S_IWUSR | S_IXUSR | S_IRGRP | S_IWGRP | S_IXGRP;
    else
        mode = S_IRUSR | S_IWUSR | S_IRGRP | S_IWGRP;
    if (chmod(fname, mode) != 0) {
        err = errno;
        warnx("Failed to set permissions on '%s': %s", fname, strerror(err));
        return -1;
    }


    if (chown(fname, uid, group->gr_gid) != 0) {
        err = errno;
        warnx("Failed to change the owner on '%s': %s", fname, strerror(err));
        return -1;
    }

    if (recursive && S_ISDIR(sb.st_mode)) {
        dir = opendir(fname);
        if (dir == NULL) {
            err = errno;
            warnx("Failed to open directory '%s': %s", fname, strerror(err));
            return -1;
        }


        rc = 0;
        while ((entry = readdir(dir)) != NULL) {
            if (strncmp(entry->d_name, ".", 1) == 0)
                continue;

            snprintf(ent, PATH_MAX, "%s/%s", fname, entry->d_name);
            rc = set_file_permissions(ent, group, recursive);
            if (rc != 0)
                break;
        }

        closedir(dir);

        if (rc != 0)
            return rc;
    }

    return 0;
}

static int set_file_permissions(const char *fname, const struct group *group,
                                bool recursive)
{
    struct stat sb;
    struct passwd *pwd;
    int err, i, rc, mode;
    bool found = false;
    uid_t uid = (uid_t)-1;
    DIR *dir;
    struct dirent *entry;
    char ent[PATH_MAX];

    pr_verbose("Setting permissions for '%s' with group '%s'", fname,
               group->gr_name);


    if (lstat(fname, &sb) != 0) {
        warnx("'%s' does not exist.", fname);
        return -1;
    }


    if (!S_ISREG(sb.st_mode) && !S_ISDIR(sb.st_mode)) {
        warnx("Skipping '%s': not a regular file or directory.", fname);
        return 0;
    }

    if (sb.st_uid != 0) {

        pwd = getpwuid(sb.st_uid);


        for (i = 0; pwd != NULL && group->gr_mem[i] != NULL; i++) {
            if (strcmp(group->gr_mem[i], pwd->pw_name) == 0) {
                found = true;
                break;
            }
        }

        if (!found)
            uid = 0; 
    }


    if (S_ISDIR(sb.st_mode))
        mode = S_IRUSR | S_IWUSR | S_IXUSR | S_IRGRP | S_IWGRP | S_IXGRP;
    else
        mode = S_IRUSR | S_IWUSR | S_IRGRP | S_IWGRP;
    if (chmod(fname, mode) != 0) {
        err = errno;
        warnx("Failed to set permissions on '%s': %s", fname, strerror(err));
        return -1;
    }


    if (chown(fname, uid, group->gr_gid) != 0) {
        err = errno;
        warnx("Failed to change the owner on '%s': %s", fname, strerror(err));
        return -1;
    }

    if (recursive && S_ISDIR(sb.st_mode)) {
        dir = opendir(fname);
        if (dir == NULL) {
            err = errno;
            warnx("Failed to open directory '%s': %s", fname, strerror(err));
            return -1;
        }


        rc = 0;
        while ((entry = readdir(dir)) != NULL) {
            if (strncmp(entry->d_name, ".", 1) == 0)
                continue;

            snprintf(ent, PATH_MAX, "%s/%s", fname, entry->d_name);
            rc = set_file_permissions(ent, group, recursive);
            if (rc != 0)
                break;
        }

        closedir(dir);

        if (rc != 0)
            return rc;
    }

    return 0;
}

CK_RV ber_decode_BIT_STRING(CK_BYTE *str,
                            CK_BYTE **data,
                            CK_ULONG *data_len, CK_ULONG *field_len)
{
    CK_ULONG len, length_octets;

    if (!str) {
        TRACE_ERROR("%s\n", ock_err(ERR_FUNCTION_FAILED));
        return CKR_FUNCTION_FAILED;
    }
    if (str[0] != 0x03) {
        TRACE_ERROR("%s\n", ock_err(ERR_FUNCTION_FAILED));
        return CKR_FUNCTION_FAILED;
    }

    if ((str[1] & 0x80) == 0) {
        len = str[1] & 0x7F;

        *data = &str[2];
        *data_len = len;
        *field_len = 1 + (1) + len;
        return CKR_OK;
    }

    length_octets = str[1] & 0x7F;

    if (length_octets == 1) {
        len = str[2];

        *data = &str[3];
        *data_len = len;
        *field_len = 1 + (1 + 1) + len;
        return CKR_OK;
    }

    if (length_octets == 2) {
        len = str[2];
        len = len << 8;
        len |= str[3];

        *data = &str[4];
        *data_len = len;
        *field_len = 1 + (1 + 2) + len;
        return CKR_OK;
    }

    if (length_octets == 3) {
        len = str[2];
        len = len << 8;
        len |= str[3];
        len = len << 8;
        len |= str[4];

        *data = &str[5];
        *data_len = len;
        *field_len = 1 + (1 + 3) + len;
        return CKR_OK;
    }


    TRACE_ERROR("%s\n", ock_err(ERR_FUNCTION_FAILED));

    return CKR_FUNCTION_FAILED;
}

CK_RV ber_decode_BIT_STRING(CK_BYTE *str, CK_ULONG str_len,
                            CK_BYTE **data,
                            CK_ULONG *data_len, CK_ULONG *field_len)
{
    CK_ULONG len, length_octets;

    if (!str || str_len < 2) {
        TRACE_ERROR("%s\n", ock_err(ERR_FUNCTION_FAILED));
        return CKR_FUNCTION_FAILED;
    }
    if (str[0] != 0x03) {
        TRACE_ERROR("%s\n", ock_err(ERR_FUNCTION_FAILED));
        return CKR_FUNCTION_FAILED;
    }

    if ((str[1] & 0x80) == 0) {
        len = str[1] & 0x7F;
        if (1 + 1 + len > str_len) {
            TRACE_ERROR("BER length is larger than encoded data.\n");
            return CKR_FUNCTION_FAILED;
        }
        if (len < 1) {
            TRACE_ERROR("BER length is too small to include the "
                        "unused-bits-byte\n");
            return CKR_FUNCTION_FAILED;
        }

        *data = &str[2];
        *data_len = len;
        *field_len = 1 + (1) + len;
        return CKR_OK;
    }

    length_octets = str[1] & 0x7F;
    if (1 + 1 + length_octets > str_len) {
        TRACE_ERROR("BER length is larger than encoded data.\n");
        return CKR_FUNCTION_FAILED;
    }

    if (length_octets == 1) {
        len = str[2];
        if (1 + (1 + 1) + len > str_len) {
            TRACE_ERROR("BER length is larger than encoded data.\n");
            return CKR_FUNCTION_FAILED;
        }
        if (len < 1) {
            TRACE_ERROR("BER length is too small to include the "
                        "unused-bits-byte\n");
            return CKR_FUNCTION_FAILED;
        }

        *data = &str[3];
        *data_len = len;
        *field_len = 1 + (1 + 1) + len;
        return CKR_OK;
    }

    if (length_octets == 2) {
        len = str[2];
        len = len << 8;
        len |= str[3];
        if (1 + (1 + 2) + len > str_len) {
            TRACE_ERROR("BER length is larger than encoded data.\n");
            return CKR_FUNCTION_FAILED;
        }
        if (len < 1) {
            TRACE_ERROR("BER length is too small to include the "
                        "unused-bits-byte\n");
            return CKR_FUNCTION_FAILED;
        }

        *data = &str[4];
        *data_len = len;
        *field_len = 1 + (1 + 2) + len;
        return CKR_OK;
    }

    if (length_octets == 3) {
        len = str[2];
        len = len << 8;
        len |= str[3];
        len = len << 8;
        len |= str[4];
        if (1 + (1 + 3) + len > str_len) {
            TRACE_ERROR("BER length is larger than encoded data.\n");
            return CKR_FUNCTION_FAILED;
        }
        if (len < 1) {
            TRACE_ERROR("BER length is too small to include the "
                        "unused-bits-byte\n");
            return CKR_FUNCTION_FAILED;
        }

        *data = &str[5];
        *data_len = len;
        *field_len = 1 + (1 + 3) + len;
        return CKR_OK;
    }


    TRACE_ERROR("%s\n", ock_err(ERR_FUNCTION_FAILED));

    return CKR_FUNCTION_FAILED;
}

