}

CK_RV ber_decode_OCTET_STRING(CK_BYTE *str, CK_ULONG str_len,
                              CK_BYTE **data,
                              CK_ULONG *data_len, CK_ULONG *field_len)
{
    CK_ULONG len, length_octets;




    if (!str || str_len < 2) {
        TRACE_ERROR("%s\n", ock_err(ERR_FUNCTION_FAILED));
        return CKR_FUNCTION_FAILED;
    }
    if (str[0] != 0x04) {
        TRACE_ERROR("%s\n", ock_err(ERR_FUNCTION_FAILED));
        return CKR_FUNCTION_FAILED;
    }


    if ((str[1] & 0x80) == 0) {
        len = str[1] & 0x7F;
        if (1 + 1 + len > str_len) {
            TRACE_ERROR("BER length is larger than encoded data.\n");
            return CKR_FUNCTION_FAILED;
        }

        *data = &str[2];
        *data_len = len;
        *field_len = 1 + (1) + len;
        return CKR_OK;
    }

    length_octets = str[1] & 0x7F;
    if (1 + 1 + length_octets > str_len) {
        TRACE_ERROR("BER length is larger than encoded data.\n");
        return CKR_FUNCTION_FAILED;
    }

    if (length_octets == 1) {
        len = str[2];
        if (1 + (1 + 1) + len > str_len) {
            TRACE_ERROR("BER length is larger than encoded data.\n");
            return CKR_FUNCTION_FAILED;
        }

        *data = &str[3];
        *data_len = len;
        *field_len = 1 + (1 + 1) + len;
        return CKR_OK;
    }

    if (length_octets == 2) {
        len = str[2];
        len = len << 8;
        len |= str[3];
        if (1 + (1 + 2) + len > str_len) {
            TRACE_ERROR("BER length is larger than encoded data.\n");
            return CKR_FUNCTION_FAILED;
        }

        *data = &str[4];
        *data_len = len;
        *field_len = 1 + (1 + 2) + len;
        return CKR_OK;
    }

    if (length_octets == 3) {
        len = str[2];
        len = len << 8;
        len |= str[3];
        len = len << 8;
        len |= str[4];
        if (1 + (1 + 3) + len > str_len) {
            TRACE_ERROR("BER length is larger than encoded data.\n");
            return CKR_FUNCTION_FAILED;
        }

        *data = &str[5];
        *data_len = len;
        *field_len = 1 + (1 + 3) + len;
        return CKR_OK;
    }


    TRACE_ERROR("%s\n", ock_err(ERR_FUNCTION_FAILED));

    return CKR_FUNCTION_FAILED;
}

CK_RV ber_decode_SEQUENCE(CK_BYTE *seq,
                          CK_BYTE **data, CK_ULONG *data_len,
                          CK_ULONG *field_len)
{
    CK_ULONG len, length_octets;


    if (!seq) {
        TRACE_ERROR("%s\n", ock_err(ERR_FUNCTION_FAILED));
