static CK_RV ica_build_ec_pub_key(OBJECT *key_obj, ICA_EC_KEY **eckey,
                                  unsigned int *privlen)
{
    CK_RV ret = CKR_OK;
    CK_ATTRIBUTE *attr;
    unsigned char x_array[ICATOK_EC_MAX_D_LEN];
    unsigned char y_array[ICATOK_EC_MAX_D_LEN];
    int rc, nid;
    CK_BYTE *ecpoint;
    CK_ULONG ecpoint_len, field_len;


    ret = ica_prepare_ec_key(key_obj, eckey, privlen, &nid);
    if (ret != CKR_OK) {
        TRACE_ERROR("ica_prepare_ec_key() failed with rc = 0x%lx. \n", ret);
        return ret;
    }


    ret = template_attribute_get_non_empty(key_obj->template, CKA_EC_POINT,
                                           &attr);
    if (ret != CKR_OK) {
        TRACE_ERROR("%s\n", ock_err(ERR_TEMPLATE_INCOMPLETE));
        ret = CKR_TEMPLATE_INCOMPLETE;
        goto end;
    }


    ret = ber_decode_OCTET_STRING(attr->pValue, &ecpoint, &ecpoint_len,
                                  &field_len);
    if (ret != CKR_OK || field_len != attr->ulValueLen) {
        TRACE_DEVEL("ber_decode_OCTET_STRING failed\n");
        ret = CKR_ATTRIBUTE_VALUE_INVALID;
        goto end;
    }


    ret = set_pubkey_coordinates(nid, ecpoint, ecpoint_len,
                                 *privlen, x_array, y_array);
    if (ret != 0) {
        TRACE_ERROR("Cannot determine public key coordinates from "
                    "given public key\n");
        goto end;
    }


    rc = p_ica_ec_key_init(x_array, y_array, NULL, *eckey);
    if (rc != 0) {
        switch (rc) {
        case ENODEV:
            TRACE_ERROR("%s\n", ock_err(ERR_FUNCTION_NOT_SUPPORTED));
            ret = CKR_FUNCTION_NOT_SUPPORTED;
            break;
        case EPERM:
            TRACE_ERROR("ica_ec_key_init() failed with rc=EPERM, probably curve not supported by openssl.\n");
            ret = CKR_CURVE_NOT_SUPPORTED;
            break;
        default:
            TRACE_ERROR("ica_ec_key_init() failed with rc = %d \n", rc);
            ret = CKR_FUNCTION_FAILED;
            break;
        }
        goto end;
    }

end:
    if (ret != CKR_OK) {
        p_ica_ec_key_free(*eckey);
        *eckey = NULL;
    }

    return ret;
}

static CK_RV ica_build_ec_pub_key(OBJECT *key_obj, ICA_EC_KEY **eckey,
                                  unsigned int *privlen)
{
    CK_RV ret = CKR_OK;
    CK_ATTRIBUTE *attr;
    unsigned char x_array[ICATOK_EC_MAX_D_LEN];
    unsigned char y_array[ICATOK_EC_MAX_D_LEN];
    int rc, nid;
    CK_BYTE *ecpoint;
    CK_ULONG ecpoint_len, field_len;


    ret = ica_prepare_ec_key(key_obj, eckey, privlen, &nid);
    if (ret != CKR_OK) {
        TRACE_ERROR("ica_prepare_ec_key() failed with rc = 0x%lx. \n", ret);
        return ret;
    }


    ret = template_attribute_get_non_empty(key_obj->template, CKA_EC_POINT,
                                           &attr);
    if (ret != CKR_OK) {
        TRACE_ERROR("%s\n", ock_err(ERR_TEMPLATE_INCOMPLETE));
        ret = CKR_TEMPLATE_INCOMPLETE;
        goto end;
    }


    ret = ber_decode_OCTET_STRING(attr->pValue, attr->ulValueLen,
                                  &ecpoint, &ecpoint_len, &field_len);
    if (ret != CKR_OK || field_len != attr->ulValueLen) {
        TRACE_DEVEL("ber_decode_OCTET_STRING failed\n");
        ret = CKR_ATTRIBUTE_VALUE_INVALID;
        goto end;
    }


    ret = set_pubkey_coordinates(nid, ecpoint, ecpoint_len,
                                 *privlen, x_array, y_array);
    if (ret != 0) {
        TRACE_ERROR("Cannot determine public key coordinates from "
                    "given public key\n");
        goto end;
    }


    rc = p_ica_ec_key_init(x_array, y_array, NULL, *eckey);
    if (rc != 0) {
        switch (rc) {
        case ENODEV:
            TRACE_ERROR("%s\n", ock_err(ERR_FUNCTION_NOT_SUPPORTED));
            ret = CKR_FUNCTION_NOT_SUPPORTED;
            break;
        case EPERM:
            TRACE_ERROR("ica_ec_key_init() failed with rc=EPERM, probably curve not supported by openssl.\n");
            ret = CKR_CURVE_NOT_SUPPORTED;
            break;
        default:
            TRACE_ERROR("ica_ec_key_init() failed with rc = %d \n", rc);
            ret = CKR_FUNCTION_FAILED;
            break;
        }
        goto end;
    }

end:
    if (ret != CKR_OK) {
        p_ica_ec_key_free(*eckey);
        *eckey = NULL;
    }

    return ret;
}

int fuse_uring_start(struct fuse_session *se)
{
	int err = 0;
	struct fuse_ring_pool *fuse_ring;

	fuse_uring_sanity_check(se);

	fuse_ring = fuse_create_ring(se);
	if (fuse_ring == NULL) {
		err = -EADDRNOTAVAIL;
		goto err;
	}

	se->uring.pool = fuse_ring;


	sem_init(&fuse_ring->init_sem, 0, 0);
	pthread_cond_init(&fuse_ring->thread_start_cond, NULL);
	pthread_mutex_init(&fuse_ring->thread_start_mutex, NULL);

	err = fuse_uring_start_ring_threads(fuse_ring);
	if (err)
		goto err;




	pthread_mutex_lock(&fuse_ring->thread_start_mutex);
	while (fuse_ring->started_threads < fuse_ring->nr_queues)
		pthread_cond_wait(&fuse_ring->thread_start_cond,
				  &fuse_ring->thread_start_mutex);

	if (fuse_ring->failed_threads != 0)
		err = -EADDRNOTAVAIL;
	pthread_mutex_unlock(&fuse_ring->thread_start_mutex);

err:
	if (err) {

		fuse_session_destruct_uring(fuse_ring);
		se->uring.pool = fuse_ring;
	}
	return err;
}

