    xmlFreeDoc(plist_doc);
}

PLIST_API void plist_from_xml(const char *plist_xml, uint32_t length, plist_t * plist)
{

    xmlSetExternalEntityLoader(plist_xml_external_entity_loader);


    xmlDocPtr plist_doc = xmlReadMemory(plist_xml, length, "plist_from_xml:memory", NULL, XML_PARSE_NONET);
    if (plist_doc) {
        xmlNodePtr root_node = xmlDocGetRootElement(plist_doc);

        xml_to_node(root_node, plist);
        xmlFreeDoc(plist_doc);
    }
}

static bool logclif_parse_reqauth_sso( int32 fd, login_session_data& sd ){
	P* p = (P*)RFIFOP( fd, 0 );

	char ip[16];
	uint32 ipl = session[fd]->client_addr;
	ip2str( ipl, ip );

	size_t token_length = p->packetLength - sizeof( *p );

	safestrncpy( sd.userid, p->username, sizeof( sd.userid ) );
	sd.clienttype = p->clienttype;

	ShowStatus( "Request for connection (SSO mode) of %s (ip: %s)\n", sd.userid, ip );

	safestrncpy( sd.passwd, p->token, token_length + 1 );

	if( login_config.use_md5_passwds ){
		MD5_String( sd.passwd, sd.passwd );
	}

	sd.passwdenc = 0;

	int32 result = login_mmo_auth( &sd, false );

	if( result == -1 ){
		logclif_auth_ok( &sd );
	}else{
		logclif_auth_failed( &sd, result );
	}

	return true;
}

