int32 chclif_parse_moveCharSlot( int32 fd, struct char_session_data* sd){
	FIFOSD_CHECK(8);

	uint16 from, to;

	from = RFIFOW(fd,2);
	to = RFIFOW(fd,4);

	RFIFOSKIP(fd,8);


	if( (charserv_config.charmove_config.char_move_enabled)==0
	|| ( (charserv_config.charmove_config.char_moves_unlimited)==0 && sd->char_moves[from] <= 0 ) ){
		chclif_moveCharSlotReply( fd, sd, from, 1 );
		return 1;
	}


	if( sd->found_char[from] <= 0 || to >= sd->char_slots ){
		chclif_moveCharSlotReply( fd, sd, from, 1 );
		return 1;
	}

	if( sd->found_char[to] > 0 ){

		if( charserv_config.charmove_config.char_movetoused ){ 

			if( SQL_ERROR == Sql_QueryStr(sql_handle, "START TRANSACTION")
				|| SQL_ERROR == Sql_Query(sql_handle, "UPDATE `%s` SET `char_num`='%d' WHERE `char_id` = '%d'",schema_config.char_db, to, sd->found_char[from] )
				|| SQL_ERROR == Sql_Query(sql_handle, "UPDATE `%s` SET `char_num`='%d' WHERE `char_id` = '%d'", schema_config.char_db, from, sd->found_char[to] )
				|| SQL_ERROR == Sql_QueryStr(sql_handle, "COMMIT")
				){
				chclif_moveCharSlotReply( fd, sd, from, 1 );
				Sql_ShowDebug(sql_handle);
				Sql_QueryStr(sql_handle,"ROLLBACK");
				return 1;
			}
		}else{

			chclif_moveCharSlotReply( fd, sd, from, 1 );
			return 1;
		}
	}else if( SQL_ERROR == Sql_Query(sql_handle, "UPDATE `%s` SET `char_num`='%d' WHERE `char_id`='%d'", schema_config.char_db, to, sd->found_char[from] ) ){
		Sql_ShowDebug(sql_handle);
		chclif_moveCharSlotReply( fd, sd, from, 1 );
		return 1;
	}

	if( (charserv_config.charmove_config.char_moves_unlimited)==0 ){
		sd->char_moves[from]--;
		Sql_Query(sql_handle, "UPDATE `%s` SET `moves`='%d' WHERE `char_id`='%d'", schema_config.char_db, sd->char_moves[from], sd->found_char[from] );
	}


	chclif_moveCharSlotReply( fd, sd, from, 0 );
	chclif_mmo_char_send(fd, sd);
	return 1;
}

int32 chclif_parse_moveCharSlot( int32 fd, struct char_session_data* sd){
	FIFOSD_CHECK(8);

	uint16 from, to;

	from = RFIFOW(fd,2);
	to = RFIFOW(fd,4);

	RFIFOSKIP(fd,8);


	if( from >= MAX_CHARS ){
		chclif_moveCharSlotReply( fd, sd, from, 1 );
		return 1;
	}


	if( (charserv_config.charmove_config.char_move_enabled)==0
	|| ( (charserv_config.charmove_config.char_moves_unlimited)==0 && sd->char_moves[from] <= 0 ) ){
		chclif_moveCharSlotReply( fd, sd, from, 1 );
		return 1;
	}


	if( sd->found_char[from] <= 0 ){
		chclif_moveCharSlotReply( fd, sd, from, 1 );
		return 1;
	}


	if( to >= MAX_CHARS ){
		chclif_moveCharSlotReply( fd, sd, from, 1 );
		return 1;
	}


	if( to >= sd->char_slots ){
		chclif_moveCharSlotReply( fd, sd, from, 1 );
		return 1;
	}

	if( sd->found_char[to] > 0 ){

		if( charserv_config.charmove_config.char_movetoused ){ 

			if( SQL_ERROR == Sql_QueryStr(sql_handle, "START TRANSACTION")
				|| SQL_ERROR == Sql_Query(sql_handle, "UPDATE `%s` SET `char_num`='%d' WHERE `char_id` = '%d'",schema_config.char_db, to, sd->found_char[from] )
				|| SQL_ERROR == Sql_Query(sql_handle, "UPDATE `%s` SET `char_num`='%d' WHERE `char_id` = '%d'", schema_config.char_db, from, sd->found_char[to] )
				|| SQL_ERROR == Sql_QueryStr(sql_handle, "COMMIT")
				){
				chclif_moveCharSlotReply( fd, sd, from, 1 );
				Sql_ShowDebug(sql_handle);
				Sql_QueryStr(sql_handle,"ROLLBACK");
				return 1;
			}
		}else{

			chclif_moveCharSlotReply( fd, sd, from, 1 );
			return 1;
		}
	}else if( SQL_ERROR == Sql_Query(sql_handle, "UPDATE `%s` SET `char_num`='%d' WHERE `char_id`='%d'", schema_config.char_db, to, sd->found_char[from] ) ){
		Sql_ShowDebug(sql_handle);
		chclif_moveCharSlotReply( fd, sd, from, 1 );
		return 1;
	}

	if( (charserv_config.charmove_config.char_moves_unlimited)==0 ){
		sd->char_moves[from]--;
		Sql_Query(sql_handle, "UPDATE `%s` SET `moves`='%d' WHERE `char_id`='%d'", schema_config.char_db, sd->char_moves[from], sd->found_char[from] );
	}


	chclif_moveCharSlotReply( fd, sd, from, 0 );
	chclif_mmo_char_send(fd, sd);
	return 1;
}

void clif_mail_removeitem( map_session_data* sd, bool success, int32 index, int32 amount ){
	PACKET_ZC_ACK_REMOVE_ITEM_MAIL p = { 0 };

	p.PacketType = rodexremoveitem;
	p.result = success;
	p.index = index;
	p.cnt = amount;

	int32 total = 0;
	for( int32 i = 0; i < MAIL_MAX_ITEM; i++ ){
		if( sd->mail.item[i].nameid == 0 ){
			break;
		}

		total += sd->mail.item[i].amount * ( sd->inventory_data[sd->mail.item[i].index]->weight / 10 );
	}

	p.weight = total;
	clif_send(&p, sizeof(p), sd, SELF);
}

void clif_mail_removeitem( map_session_data* sd, bool success, int32 index, int32 amount ){
	PACKET_ZC_ACK_REMOVE_ITEM_MAIL p = { 0 };

	p.PacketType = rodexremoveitem;
	p.result = success;
	p.index = index;
	p.cnt = amount;

	int32 total = 0;
	for( int32 i = 0; i < MAIL_MAX_ITEM; i++ ){
		if( sd->mail.item[i].nameid == 0 ){
			break;
		}

		if( sd->mail.item[i].index < 0 || sd->mail.item[i].index >= MAX_INVENTORY ){
			continue;
		}

		item_data* id = sd->inventory_data[sd->mail.item[i].index];

		if( id == nullptr ){
			continue;
		}

		total += sd->mail.item[i].amount * ( id->weight / 10 );
	}

	p.weight = total;
	clif_send(&p, sizeof(p), sd, SELF);
}

