static void
ecma_op_internal_buffer_append (ecma_collection_t *container_p, 
                                ecma_value_t key_arg, 
                                ecma_value_t value_arg, 
                                lit_magic_string_id_t lit_id) 
{
  JERRY_ASSERT (container_p != NULL);

  ecma_collection_push_back (container_p, ecma_copy_value_if_not_object (key_arg));

  if (lit_id == LIT_MAGIC_STRING_WEAKMAP_UL || lit_id == LIT_MAGIC_STRING_MAP_UL)
  {
    ecma_collection_push_back (container_p, ecma_copy_value_if_not_object (value_arg));
  }

  ECMA_CONTAINER_SET_SIZE (container_p, ECMA_CONTAINER_GET_SIZE (container_p) + 1);
}

static void
ecma_op_internal_buffer_append (ecma_collection_t *container_p, 
                                ecma_value_t key_arg, 
                                ecma_value_t value_arg, 
                                lit_magic_string_id_t lit_id) 
{
  JERRY_ASSERT (container_p != NULL);

  if (lit_id == LIT_MAGIC_STRING_WEAKMAP_UL || lit_id == LIT_MAGIC_STRING_MAP_UL)
  {
    ecma_value_t values[] = { ecma_copy_value_if_not_object (key_arg), ecma_copy_value_if_not_object (value_arg) };
    ecma_collection_append (container_p, values, 2);
  }
  else
  {
    ecma_collection_push_back (container_p, ecma_copy_value_if_not_object (key_arg));
  }

  ECMA_CONTAINER_SET_SIZE (container_p, ECMA_CONTAINER_GET_SIZE (container_p) + 1);
}

ecma_value_t
ecma_proxy_object_get (ecma_object_t *obj_p, 
                       ecma_string_t *prop_name_p, 
                       ecma_value_t receiver) 
{
  JERRY_ASSERT (ECMA_OBJECT_IS_PROXY (obj_p));
  ECMA_CHECK_STACK_USAGE ();

  ecma_proxy_object_t *proxy_obj_p = (ecma_proxy_object_t *) obj_p;


  ecma_value_t handler = proxy_obj_p->handler;


  ecma_value_t trap = ecma_validate_proxy_object (handler, LIT_MAGIC_STRING_GET);


  if (ECMA_IS_VALUE_ERROR (trap))
  {
    return trap;
  }


  if (ecma_is_value_undefined (trap))
  {
    ecma_object_t *target_obj_p = ecma_get_object_from_value (proxy_obj_p->target);
    ecma_value_t result = ecma_op_object_get_with_receiver (target_obj_p, prop_name_p, receiver);
    JERRY_BLOCK_TAIL_CALL_OPTIMIZATION ();
    return result;
  }

  ecma_object_t *func_obj_p = ecma_get_object_from_value (trap);
  ecma_value_t prop_value = ecma_make_prop_name_value (prop_name_p);
  ecma_value_t args[] = { proxy_obj_p->target, prop_value, receiver };


  ecma_value_t trap_result = ecma_op_function_call (func_obj_p, handler, args, 3);

  ecma_deref_object (func_obj_p);


  if (ECMA_IS_VALUE_ERROR (trap_result) || (obj_p->u2.prototype_cp & JERRY_PROXY_SKIP_RESULT_VALIDATION))
  {
    return trap_result;
  }


  ecma_property_descriptor_t target_desc;
  ecma_value_t status = ecma_op_get_own_property_descriptor (proxy_obj_p->target, prop_name_p, &target_desc);


  if (ECMA_IS_VALUE_ERROR (status))
  {
    ecma_free_value (trap_result);
    return status;
  }


  if (ecma_is_value_true (status))
  {
    ecma_value_t ret_value = ECMA_VALUE_EMPTY;

    if ((target_desc.flags & JERRY_PROP_IS_VALUE_DEFINED) && !(target_desc.flags & JERRY_PROP_IS_CONFIGURABLE)
        && !(target_desc.flags & JERRY_PROP_IS_WRITABLE) && !ecma_op_same_value (trap_result, target_desc.value))
    {
      ret_value = ecma_raise_type_error (ECMA_ERR_INCORRECT_RETURN_PROXY_GET_TRAP);
    }
    else if (!(target_desc.flags & JERRY_PROP_IS_CONFIGURABLE)
             && (target_desc.flags & (JERRY_PROP_IS_GET_DEFINED | JERRY_PROP_IS_SET_DEFINED))
             && target_desc.get_p == NULL && !ecma_is_value_undefined (trap_result))
    {
      ret_value = ecma_raise_type_error (ECMA_ERR_PROXY_PROPERTY_NOT_CONFIGURABLE_NOT_HAVE_GETTER);
    }

    ecma_free_property_descriptor (&target_desc);

    if (ECMA_IS_VALUE_ERROR (ret_value))
    {
      ecma_free_value (trap_result);

      return ret_value;
    }
  }


  return trap_result;
}

ecma_value_t
ecma_proxy_object_get (ecma_object_t *obj_p, 
                       ecma_string_t *prop_name_p, 
                       ecma_value_t receiver) 
{
  JERRY_ASSERT (ECMA_OBJECT_IS_PROXY (obj_p));
  ECMA_CHECK_STACK_USAGE ();

  ecma_proxy_object_t *proxy_obj_p = (ecma_proxy_object_t *) obj_p;


  ecma_value_t handler = proxy_obj_p->handler;


  ecma_value_t trap = ecma_validate_proxy_object (handler, LIT_MAGIC_STRING_GET);


  if (ECMA_IS_VALUE_ERROR (trap))
  {
    return trap;
  }


  if (ecma_is_value_undefined (trap))
  {
    ecma_object_t *target_obj_p = ecma_get_object_from_value (proxy_obj_p->target);
    ecma_value_t result = ecma_op_object_get_with_receiver (target_obj_p, prop_name_p, receiver);
    JERRY_BLOCK_TAIL_CALL_OPTIMIZATION ();
    return result;
  }

  ecma_object_t *func_obj_p = ecma_get_object_from_value (trap);
  ecma_value_t prop_value = ecma_make_prop_name_value (prop_name_p);
  ecma_value_t args[] = { proxy_obj_p->target, prop_value, receiver };


  ecma_ref_object (obj_p);
  ecma_value_t trap_result = ecma_op_function_call (func_obj_p, handler, args, 3);
  ecma_deref_object (obj_p);

  ecma_deref_object (func_obj_p);


  if (ECMA_IS_VALUE_ERROR (trap_result) || (obj_p->u2.prototype_cp & JERRY_PROXY_SKIP_RESULT_VALIDATION))
  {
    return trap_result;
  }


  ecma_property_descriptor_t target_desc;
  ecma_value_t status = ecma_op_get_own_property_descriptor (proxy_obj_p->target, prop_name_p, &target_desc);


  if (ECMA_IS_VALUE_ERROR (status))
  {
    ecma_free_value (trap_result);
    return status;
  }


  if (ecma_is_value_true (status))
  {
    ecma_value_t ret_value = ECMA_VALUE_EMPTY;

    if ((target_desc.flags & JERRY_PROP_IS_VALUE_DEFINED) && !(target_desc.flags & JERRY_PROP_IS_CONFIGURABLE)
        && !(target_desc.flags & JERRY_PROP_IS_WRITABLE) && !ecma_op_same_value (trap_result, target_desc.value))
    {
      ret_value = ecma_raise_type_error (ECMA_ERR_INCORRECT_RETURN_PROXY_GET_TRAP);
    }
    else if (!(target_desc.flags & JERRY_PROP_IS_CONFIGURABLE)
             && (target_desc.flags & (JERRY_PROP_IS_GET_DEFINED | JERRY_PROP_IS_SET_DEFINED))
             && target_desc.get_p == NULL && !ecma_is_value_undefined (trap_result))
    {
      ret_value = ecma_raise_type_error (ECMA_ERR_PROXY_PROPERTY_NOT_CONFIGURABLE_NOT_HAVE_GETTER);
    }

    ecma_free_property_descriptor (&target_desc);

    if (ECMA_IS_VALUE_ERROR (ret_value))
    {
      ecma_free_value (trap_result);

      return ret_value;
    }
  }


  return trap_result;
}

int
ge25519_is_on_main_subgroup(const ge25519_p3 *p)
{
    ge25519_p3 pl;

    ge25519_mul_l(&pl, p);

    return fe25519_iszero(pl.X);
}

int
ge25519_is_on_main_subgroup(const ge25519_p3 *p)
{
    ge25519_p3 pl;
    fe25519    t;

    ge25519_mul_l(&pl, p);

    fe25519_sub(t, pl.Y, pl.Z);

    return fe25519_iszero(pl.X) & fe25519_iszero(t);
}

unsigned int add_ch(unsigned char ch, unsigned char* buf, unsigned int idx) {

    if (idx >= MAX_ALN) {
        verbprintf(3, "FLEX: idx %u >= MAX_ALN %u\n", idx, MAX_ALN);
        return 0;
    }










    if (ch == 0x09 && idx < (MAX_ALN - 2)) {  
        buf[idx] = '\\';
        buf[idx + 1] = 't';
        return 2;
    }
    if (ch == 0x0a && idx < (MAX_ALN - 2)) {  
        buf[idx] = '\\';
        buf[idx + 1] = 'n';
        return 2;
    }
    if (ch == 0x0d && idx < (MAX_ALN - 2)) {  
        buf[idx] = '\\';
        buf[idx + 1] = 'r';
        return 2;
    }

    if (ch >= 32 && ch <= 126) {
        buf[idx] = ch;
        return 1;
    }





    return 0;
}

