    if (ch == 0x0d && idx < (MAX_ALN - 2)) {  
        buf[idx] = '\\';
        buf[idx + 1] = 'r';
        return 2;
    }



    if (ch == '%') {
        if (idx < (MAX_ALN - 2)) {
            buf[idx] = '%';
